insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_128'
from (values
('127.877.d.1.A',3,'A lube-bay trainee patiently explains a recommended service to a customer who speaks little English, using the vehicle''s gauges and simple words. He is demonstrating:','["effective oral communication with individuals from varied backgrounds", "unclear answers", "rushed talking", "avoiding customers"]'::jsonb,0,'Adapt communication.','original'),
('127.877.d.1.A',4,'A customer says her car ''makes a funny noise sometimes.'' The best follow-up from the technician is:','["ending the conversation", "asking when the noise happens and what it sounds like", "telling her to come back later", "guessing at the cause"]'::jsonb,1,'Gather details.','original'),
('127.877.d.1.B',3,'A technician writes the complaint, the cause and the correction on a repair order after replacing a worn belt. This shows:','["skipped records", "vague notes", "effective written communication, including documentation", "slang"]'::jsonb,2,'Documentation.','original'),
('127.877.d.1.B',4,'Which line is the most useful on a repair order?','["''Looked fine''", "''Did stuff''", "''Fixed it''", "''Replaced serpentine belt; tension tested at spec''"]'::jsonb,3,'Specific and verifiable.','original'),
('127.877.d.1.C',3,'A technician adds a $48 part, 2.5 hours of labor at $88 an hour and 7 percent tax on the part. She is demonstrating:','["mathematical skills for estimating a repair bill", "guessing", "avoiding numbers", "ignoring tax"]'::jsonb,0,'Compute totals.','original'),
('127.877.d.1.C',4,'Labor is 1.5 hours at $100 per hour and parts are $62. The total before tax is:','["$262", "$212", "$162", "$150"]'::jsonb,1,'150 + 62 = 212.','original'),
('127.877.d.2.A',3,'Before an inspection, a technician opens the owner''s manual to find when the timing belt and fluids are due for service. She is:','["ignoring the manual", "guessing intervals", "locating the manufacturer''s recommended preventative maintenance schedule", "skipping service"]'::jsonb,2,'Use the schedule.','original'),
('127.877.d.2.A',4,'A ''severe service'' schedule in an owner''s manual applies to vehicles that:','["are brand new", "are only washed", "never leave the garage", "tow, idle a lot or drive in dusty or short-trip conditions"]'::jsonb,3,'Harsh use.','original'),
('127.877.d.2.B',3,'A technician runs a checklist of tires, brakes, belts, lights, fluids and suspension on a customer''s car. She is performing:','["a preventative maintenance inspection of vehicle systems", "a paint job", "a body repair", "a sale"]'::jsonb,0,'PM inspection.','original'),
('127.877.d.2.B',4,'Why is a preventative maintenance inspection done even when the car seems fine?','["to waste time", "to find wear before it causes a breakdown", "to avoid work", "to raise the bill"]'::jsonb,1,'Prevent failures.','original'),
('127.877.d.2.C',3,'A student names the control arms, ball joints, springs and steering knuckle on a diagram of a front suspension. She is describing:','["paint layers", "radio parts", "the function of automotive chassis components", "engine parts"]'::jsonb,2,'Chassis parts.','original'),
('127.877.d.2.C',4,'Springs in a suspension system mainly:','["brake the wheels", "cool the engine", "steer the vehicle", "support the vehicle''s weight and absorb road shocks"]'::jsonb,3,'Springs support and absorb.','original'),
('127.877.d.2.D',3,'A technician follows a wiring schematic and a technical service bulletin to find the cause of an intermittent dome-light problem. She is:','["locating, reading and interpreting service repair information", "using memory only", "ignoring data", "guessing"]'::jsonb,0,'Schematics and bulletins.','original'),
('127.877.d.2.D',4,'A technical service bulletin is most useful because it:','["advertises accessories", "describes known problems and approved fixes for specific vehicles", "gives driving tips", "lists car prices"]'::jsonb,1,'TSBs document known issues.','original'),
('127.877.d.2.E',3,'A technician compares a measured brake rotor thickness with the published minimum and decides to replace it. She is:','["painting", "guessing", "using published specifications to diagnose component wear", "ignoring specs"]'::jsonb,2,'Compare to spec.','original'),
('127.877.d.2.E',4,'A rotor measures below the ''minimum thickness'' stamped on it. The technician should:','["machine it thinner", "reuse it as is", "paint it", "replace the rotor"]'::jsonb,3,'Below minimum means replace.','original'),
('127.877.d.2.F',3,'A technician looks up the oil grade and capacity for a customer''s engine, such as 5W-30 and 4.5 quarts. She is:','["identifying the appropriate oil viscosity and capacity", "guessing", "using any oil", "skipping specs"]'::jsonb,0,'Use the specified oil.','original'),
('127.877.d.2.F',4,'In ''5W-30'' oil, the ''5W'' indicates how the oil flows:','["when hot only", "when cold", "in water", "after 5 weeks"]'::jsonb,1,'W stands for winter.','original'),
('127.877.d.2.G',3,'When the ignition is switched on, a technician notes that the oil-pressure, check-engine and charging lights glow briefly and then go out. She is:','["ignoring lights", "painting", "verifying the operation of the instrument panel engine warning indicators", "guessing"]'::jsonb,2,'Bulb check.','original'),
('127.877.d.2.G',4,'A warning light that never comes on during the bulb check may indicate:','["a full tank", "a perfect system", "a new battery", "a burned-out bulb or a circuit fault"]'::jsonb,3,'No bulb check is suspicious.','original'),
('127.877.d.2.H',3,'A technician looks over an engine and records a seeping valve cover gasket, low coolant and a cracked hose. She is:','["inspecting the engine assembly and documenting findings of fuel, oil, coolant and other leaks", "painting", "guessing", "ignoring leaks"]'::jsonb,0,'Document leaks.','original'),
('127.877.d.2.H',4,'A fresh, wet oil stain below a valve cover most likely means:','["a clean engine", "a leaking valve cover gasket", "a bad tire", "a dead battery"]'::jsonb,1,'Locate the source.','original'),
('127.877.d.2.I',3,'A technician uses a tap, a thread-repair insert and a screw extractor to fix a stripped oil-pan hole and remove a broken bolt. She is performing:','["guessing", "avoiding repair", "common fastener and thread repair", "painting"]'::jsonb,2,'Thread repair.','original'),
('127.877.d.2.I',4,'A thread-repair insert is used to:','["enlarge a hole permanently", "cut new bolts", "paint a hole", "restore damaged threads to their original size"]'::jsonb,3,'Insert restores threads.','original'),
('127.877.d.2.J',3,'A technician checks the serpentine belt for cracks, tests the automatic tensioner and aligns the pulleys. She is:','["inspecting, replacing and adjusting drive belts, tensioners and pulleys", "ignoring belts", "guessing", "painting"]'::jsonb,0,'Belt service.','original'),
('127.877.d.2.J',4,'A squealing belt that shows glazing on its edges most likely needs:','["more oil", "replacement or retensioning", "more air", "a new tire"]'::jsonb,1,'Glazed belts slip.','original'),
('127.877.d.2.K',3,'A technician drains the old oil, installs a new filter with a lightly oiled gasket and refills to the specified capacity. She is performing:','["a coolant flush", "a fuel change", "an engine oil and filter change", "a tire change"]'::jsonb,2,'Oil change.','original'),
('127.877.d.2.K',4,'After an oil change, the technician should start the engine and check for:','["a loose antenna", "bad tires", "a dirty windshield", "leaks and the correct oil level on the dipstick"]'::jsonb,3,'Verify the job.','original'),
('127.877.d.2.L',3,'A technician connects red to the dead battery''s positive, red to the donor''s positive, black to the donor''s negative and the final black clamp to engine ground. She is:','["explaining and performing a jump-start", "recharging a phone", "guessing", "painting"]'::jsonb,0,'Correct order.','original'),
('127.877.d.2.L',4,'Reversing the jumper cable connections on modern vehicles can:','["improve charging", "damage electronic modules and cause a fire", "do nothing", "speed the repair"]'::jsonb,1,'Polarity matters.','original'),
('127.877.d.3.A',3,'Before using an air ratchet and a torque wrench on wheel nuts, a technician checks the tool and wears eye protection. She is demonstrating:','["misusing tools", "ignoring safety", "the proper use of hand and power tools and equipment common to the trade", "careless use"]'::jsonb,2,'Tool safety.','original'),
('127.877.d.3.A',4,'Using a wrench with a cheater pipe to tighten a bolt is unsafe mainly because it can:','["save time", "improve accuracy", "save tools", "slip, break or over-tighten and cause injury"]'::jsonb,3,'Misuse hazards.','original'),
('127.877.d.3.B',3,'A technician pours used coolant into a labeled container for recycling instead of the shop drain. She is practicing:','["the proper handling and disposal of environmentally hazardous materials", "ignoring rules", "careless disposal", "dumping"]'::jsonb,0,'Hazmat practice.','original'),
('127.877.d.3.B',4,'Used engine oil rags and filters should be:','["burned outdoors", "stored in approved containers and disposed of per regulations", "thrown in the drain", "left on the floor"]'::jsonb,1,'Regulated waste.','original'),
('127.877.d.4.A',3,'A student explains that pressure applied to a fluid in a closed system is transmitted equally in all directions, which lets a small pedal force move large caliper pistons. She is explaining:','["Boyle''s law", "Newton''s law of gravity", "Pascal''s law as it relates to the brake system", "Ohm''s law"]'::jsonb,2,'Pascal''s principle.','original'),
('127.877.d.4.A',4,'A master cylinder piston with 1 square inch of area pushes with 50 pounds. The pressure created is:','["500 psi", "5 psi", "0.02 psi", "50 psi"]'::jsonb,3,'50 ÷ 1 = 50.','original'),
('127.877.d.4.B',3,'A technician checks the master cylinder fluid level, brake lines, hoses and the pedal for leaks and damage. She is:','["inspecting brake system components", "tuning the radio", "washing the car", "painting calipers"]'::jsonb,0,'Inspect the system.','original'),
('127.877.d.4.B',4,'A brake hose that bulges when the pedal is pressed should be:','["taped", "replaced immediately", "painted", "ignored"]'::jsonb,1,'Bulging hose may burst.','original'),
('127.877.d.4.C',3,'A technician measures a drum''s inside diameter with a drum micrometer and compares it with the maximum diameter cast on the drum. She is:','["ignoring specs", "painting", "inspecting, measuring and refinishing a brake drum to specification", "guessing"]'::jsonb,2,'Measure then refinish.','original'),
('127.877.d.4.C',4,'If a brake drum is machined beyond its discard diameter, it should be:','["reused", "painted", "machined again", "replaced, because it is too thin and may fail"]'::jsonb,3,'Discard diameter is a limit.','original'),
('127.877.d.4.D',3,'A technician removes a drum, then cleans and checks the shoes, springs, pins, clips and levers for wear. She is:','["removing, cleaning and inspecting the drum brake hardware", "ignoring wear", "guessing", "painting"]'::jsonb,0,'Inspect hardware.','original'),
('127.877.d.4.D',4,'Brake dust should be cleaned with an approved wet method or vacuum rather than blown with compressed air because:','["it looks messier", "dust can contain harmful particles", "it saves time", "it saves money"]'::jsonb,1,'Avoid airborne dust.','original'),
('127.877.d.4.E',3,'A technician applies high-temperature grease to the backing-plate pads, reassembles the shoes and sets the star adjuster so the drum just slides on. She is:','["avoiding service", "guessing", "lubricating, reassembling and pre-adjusting the shoes and parking brake", "painting"]'::jsonb,2,'Pre-adjust.','original'),
('127.877.d.4.E',4,'Grease should not be allowed to contact:','["the adjuster threads", "the pivot pins", "the backing-plate pads", "the brake lining surface"]'::jsonb,3,'Grease ruins friction.','original'),
('127.877.d.4.F',3,'A technician removes the pads, inspects the caliper slides and boots, cleans and lubricates them and reassembles the caliper. She is performing:','["service on the disc brake caliper and pads", "a tire change", "an alignment", "an oil change"]'::jsonb,0,'Caliper service.','original'),
('127.877.d.4.F',4,'A caliper that sticks on its slide pins may cause:','["longer pad life", "uneven pad wear and a pull to one side", "perfect braking", "a quieter ride"]'::jsonb,1,'Sticking slides.','original'),
('127.877.d.4.G',3,'A technician machines a rotor on a lathe and then measures its final thickness against the minimum specification. She is:','["guessing", "ignoring spec", "refinishing a rotor and measuring its thickness", "painting"]'::jsonb,2,'Machine and measure.','original'),
('127.877.d.4.G',4,'A rotor that has been machined below the minimum thickness is likely to:','["brake better", "last longer", "weigh more", "overheat and crack"]'::jsonb,3,'Thin rotors fail.','original'),
('127.877.d.4.H',3,'On a rear caliper with an integral parking brake, a technician uses a special tool to rotate and retract the piston. She is:','["retracting and re-adjusting the caliper piston on an integral parking brake system", "tuning the radio", "painting", "guessing"]'::jsonb,0,'Wind back the piston.','original'),
('127.877.d.4.H',4,'Forcing a rear caliper piston straight in with a C-clamp on an integral parking brake caliper can:','["speed it safely", "damage the piston and adjuster mechanism", "improve the repair", "fix the pad"]'::jsonb,1,'Use the proper tool.','original'),
('127.877.d.4.I',3,'A technician presses the brake pedal with the engine off, then starts the engine and notes how far the pedal sinks. She is checking:','["fuel economy", "tire wear", "pedal travel with and without the engine running to verify power assist operation", "radio volume"]'::jsonb,2,'Test the booster.','original'),
('127.877.d.4.I',4,'When a vacuum brake booster is working, starting the engine with the pedal held down should make the pedal:','["rise hard", "shake violently", "stay unchanged", "drop slightly as the booster assists"]'::jsonb,3,'Booster adds assist.','original'),
('127.877.d.4.J',3,'A technician pumps the pedal until it is firm with the engine off, holds it, and starts the engine to see what happens. She is:','["verifying the operation of the power-assist system", "painting rotors", "washing the brakes", "testing a tire"]'::jsonb,0,'Booster check.','original'),
('127.877.d.4.J',4,'If the pedal does not move down at all after starting the engine, the likely problem is:','["worn tires", "a faulty booster or a lack of vacuum supply", "low washer fluid", "a dead radio"]'::jsonb,1,'No assist.','original'),
('127.877.d.4.K',3,'A technician connects a gauge to the intake manifold and reads the vacuum that feeds the brake booster. She is:','["measuring tire air", "checking oil", "checking the vacuum supply from the manifold or auxiliary pump to the vacuum-type booster", "testing fuel"]'::jsonb,2,'Vacuum supply.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_128'
from (values
('127.877.d.4.K',4,'Low engine vacuum at the booster is most likely to cause:','["better mileage", "a soft tire", "a louder radio", "a hard brake pedal and reduced assist"]'::jsonb,3,'Less assist.','original'),
('127.877.d.4.L',3,'A student explains that a hybrid''s electric motor acts as a generator when the driver slows down, sending energy to the battery. She is describing:','["the operation of a regenerative braking system", "a tire rotation", "a hand brake", "an exhaust system"]'::jsonb,0,'Regeneration.','original'),
('127.877.d.4.L',4,'Regenerative braking improves efficiency because it:','["uses more fuel", "recovers some motion energy that would be lost as heat", "wastes energy", "adds more friction"]'::jsonb,1,'Energy recovery.','original'),
('127.877.d.5.A',3,'A student compares how current flows when three bulbs are connected in a single loop and when they are connected side by side. She is demonstrating:','["fuel flow", "brake lines", "knowledge of series, parallel and series-parallel circuits", "tire patterns"]'::jsonb,2,'Circuit types.','original'),
('127.877.d.5.A',4,'In a series circuit, if one bulb burns out, the other bulbs:','["turn on twice", "get brighter", "stay on", "go out, because the path is broken"]'::jsonb,3,'One path.','original'),
('127.877.d.5.B',3,'A technician sets her meter to DC volts and reads 12.6 volts across the battery terminals. She is demonstrating:','["proper use of a digital multimeter to measure voltage", "tire testing", "brake testing", "fuel testing"]'::jsonb,0,'DMM use.','original'),
('127.877.d.5.B',4,'To measure resistance with a digital multimeter, the circuit should be:','["live with the engine running", "de-energized and the component isolated", "fully powered", "overloaded"]'::jsonb,1,'Never measure ohms on a live circuit.','original'),
('127.877.d.5.C',3,'A technician follows lines on a wiring diagram from the fuse, through a switch and relay, to the horn. She is:','["measuring oil", "guessing", "using wiring diagrams to trace electrical circuits", "painting"]'::jsonb,2,'Trace the circuit.','original'),
('127.877.d.5.C',4,'On a wiring diagram, a zig-zag line usually represents a:','["fuse", "switch", "battery", "resistor"]'::jsonb,3,'Standard symbols.','original'),
('127.877.d.5.D',3,'A technician learns that a wire rubbing on the body can cause a fuse to blow repeatedly. She is demonstrating knowledge of:','["the causes and effects of shorts, grounds, opens and resistance problems", "fluid levels", "tire wear", "paint finishes"]'::jsonb,0,'Circuit faults.','original'),
('127.877.d.5.D',4,'An ''open'' in a wiring circuit means:','["current flows too much", "there is a break in the path and current cannot flow", "the circuit is perfect", "the battery is full"]'::jsonb,1,'Open equals break.','original'),
('127.877.d.5.E',3,'A technician checks that a replacement battery matches the vehicle''s required cold cranking amps and group size. She is:','["guessing", "painting", "confirming proper battery capacity for the vehicle application", "ignoring ratings"]'::jsonb,2,'Match the battery.','original'),
('127.877.d.5.E',4,'Cold cranking amps (CCA) rating measures a battery''s ability to:','["light the radio", "fill the tank", "charge the tires", "start an engine in cold temperatures"]'::jsonb,3,'CCA means cold start power.','original'),
('127.877.d.5.F',3,'A technician measures 12.2 volts at rest across a battery and compares it with a chart to estimate its charge. She is performing:','["a battery state-of-charge test", "an alignment", "a tire test", "a brake test"]'::jsonb,0,'Voltage indicates charge.','original'),
('127.877.d.5.F',4,'A fully charged 12-volt battery at rest should read about:','["6 volts", "12.6 volts", "9 volts", "14.5 volts"]'::jsonb,1,'Full charge is 12.6.','original'),
('127.877.d.5.G',3,'A technician scrubs corrosion from the terminals, tops off the cells with distilled water where possible and checks the case for cracks. She is:','["painting", "guessing", "inspecting and cleaning the battery and checking its condition", "ignoring corrosion"]'::jsonb,2,'Battery care.','original'),
('127.877.d.5.G',4,'Baking soda and water are commonly used to clean battery terminals because they:','["paint the terminals", "raise the voltage", "add acid", "neutralize acid corrosion"]'::jsonb,3,'Neutralizes acid.','original'),
('127.877.d.5.H',3,'A technician clamps an amp probe on the starter cable and reads the current while the engine cranks. She is performing:','["a starter current draw test", "a fuel test", "an oil test", "a tire test"]'::jsonb,0,'Starter draw.','original'),
('127.877.d.5.H',4,'A starter that draws much more current than the specification usually has:','["a perfect motor", "a worn or binding starter, or a mechanical problem", "a new battery only", "low washer fluid"]'::jsonb,1,'High draw means trouble.','original'),
('127.877.d.5.I',3,'A technician uses a test light and a meter to check a blown fuse, a tripped circuit breaker and a clicking relay. She is:','["washing wipers", "painting wires", "inspecting and testing fusible links, circuit breakers, fuses and relays", "guessing"]'::jsonb,2,'Protection devices.','original'),
('127.877.d.5.I',4,'A fuse should always be replaced with one that has:','["a higher amp rating", "a much lower rating", "no rating", "the same amp rating as the original"]'::jsonb,3,'Match the rating.','original'),
('127.877.d.5.J',3,'With the engine running at 2,000 rpm, a technician measures 14.2 volts at the battery and compares it with the specification. She is performing:','["a charging system output test", "a fuel test", "a tire test", "a brake test"]'::jsonb,0,'Charging output.','original'),
('127.877.d.5.J',4,'A charging system voltage under 12 volts with the engine running suggests:','["a perfect charge", "the alternator is not charging", "an overcharge", "a bad tire"]'::jsonb,1,'Alternator trouble.','original'),
('127.877.d.5.K',3,'A technician inspects the alternator belt for cracks, checks its tension and examines the pulley. She is:','["guessing", "painting", "inspecting, adjusting or replacing the alternator drive belt", "ignoring belts"]'::jsonb,2,'Belt and pulley.','original'),
('127.877.d.5.K',4,'A loose alternator belt can cause:','["better mileage", "extra charging", "a cooler engine", "low charging output and a squeal"]'::jsonb,3,'Slipping belt.','original'),
('127.877.d.5.L',3,'A technician turns the key on and verifies that the fuel, temperature and battery gauges and warning lights respond. She is:','["verifying the operation of instrument panel gauges and warning lights", "painting", "skipping checks", "guessing"]'::jsonb,0,'Dash check.','original'),
('127.877.d.5.L',4,'A temperature gauge stuck at cold with a hot engine may indicate:','["an oil change due", "a faulty sender or gauge circuit", "low tire pressure", "a perfect system"]'::jsonb,1,'Faulty sensor.','original'),
('127.877.d.5.M',3,'A technician walks around the car checking headlights, brake lights, turn signals and sockets for corrosion. She is:','["painting", "ignoring lights", "inspecting interior and exterior lamps and sockets", "guessing"]'::jsonb,2,'Lamp check.','original'),
('127.877.d.5.M',4,'If a single turn-signal blinks much faster than normal, the likely cause is:','["a clean windshield", "a new battery", "a full tank", "a burned-out bulb on that side"]'::jsonb,3,'Fast flash means bulb out.','original'),
('127.877.d.5.N',3,'A technician tests the wiper speeds and the washer spray and installs new blades on a car with streaking. She is:','["verifying windshield wiper and washer operation and replacing blades", "painting", "ignoring wipers", "guessing"]'::jsonb,0,'Wipers.','original'),
('127.877.d.5.N',4,'Wiper blades that leave streaks and chatter across the glass most likely need:','["a new tire", "replacement because the rubber is worn", "more washer fluid only", "an alignment"]'::jsonb,1,'Worn blades streak.','original'),
('127.877.d.6.A',3,'A technician checks the underhood label to identify whether the A/C uses R-134a or R-1234yf and puts on gloves and goggles. She is:','["ignoring labels", "avoiding safety", "identifying the refrigerant type and the safety and environmental concerns", "guessing"]'::jsonb,2,'Know your refrigerant.','original'),
('127.877.d.6.A',4,'Venting refrigerant into the air is a problem because it:','["is harmless", "saves money legally", "is required", "harms the environment and is regulated by law"]'::jsonb,3,'Recover refrigerant.','original'),
('127.877.d.6.B',3,'A technician squeezes the upper and lower radiator and heater hoses on a cold engine, looking for cracks, swelling or soft spots. She is:','["inspecting the engine cooling and heater system hoses", "ignoring hoses", "painting", "guessing"]'::jsonb,0,'Hose check.','original'),
('127.877.d.6.B',4,'A coolant hose that feels mushy near the clamp should be:','["taped", "replaced before it bursts", "ignored", "painted"]'::jsonb,1,'Soft hoses fail.','original'),
('127.877.d.6.C',3,'A technician switches the climate control through every mode, checking that air comes from each outlet and replaces a dirty cabin filter. She is:','["guessing", "ignoring vents", "inspecting the A/C-heater ducts, doors, hoses, cabin filters and outlets", "painting"]'::jsonb,2,'Climate check.','original'),
('127.877.d.6.C',4,'A clogged cabin air filter commonly causes:','["better braking", "a stronger blower", "brighter lights", "weak airflow from the vents and musty odors"]'::jsonb,3,'Dirty filter restricts air.','original'),
('127.877.d.6.D',3,'A technician looks through the grille and finds bugs and leaves packed across the front of the A/C condenser. She is:','["inspecting the condenser for airflow restrictions", "painting", "ignoring debris", "guessing"]'::jsonb,0,'Clear airflow.','original'),
('127.877.d.6.D',4,'A condenser blocked by debris reduces A/C performance because it:','["filters air", "cannot shed heat from the refrigerant", "stores fuel", "cools too much"]'::jsonb,1,'Heat rejection.','original'),
('127.877.d.6.E',3,'A technician notes that the A/C compressor in a hybrid is driven by a high-voltage motor and follows the service precautions. She is:','["painting", "guessing", "identifying hybrid vehicle A/C electrical circuits and the service precautions", "ignoring risks"]'::jsonb,2,'High-voltage awareness.','original'),
('127.877.d.6.E',4,'Before servicing high-voltage components on a hybrid, a technician should:','["skip the manual", "touch orange cables bare-handed", "guess the voltage", "follow the manufacturer''s procedure and wear insulated gloves"]'::jsonb,3,'Orange cables are high voltage.','original'),
('127.877.d.7.A',3,'A technician compares ATF used in an automatic transmission and gear oil used in a manual gearbox. She is:','["identifying the different fluid types used in automatic and manual transmissions", "comparing tires", "comparing paints", "comparing wipers"]'::jsonb,0,'Right fluid.','original'),
('127.877.d.7.A',4,'Using the wrong fluid in an automatic transmission can:','["extend life", "cause slipping and damage", "save fuel", "improve shifting"]'::jsonb,1,'Specified fluid only.','original'),
('127.877.d.7.B',3,'A technician checks the service manual to find a transaxle''s fluid type and refill capacity before a service. She is:','["ignoring data", "using any fluid", "identifying the fluid type and capacity required using service information", "guessing"]'::jsonb,2,'Look it up.','original'),
('127.877.d.7.B',4,'Overfilling a transmission with fluid can cause:','["longer life", "quieter shifting", "better cooling", "foaming and leaks"]'::jsonb,3,'Overfill is harmful.','original'),
('127.877.d.7.C',3,'A technician warms the engine, shifts through the gears, and checks the dipstick for the proper level. She is:','["checking the fluid level in a transmission equipped with a dipstick", "checking oil", "checking washer fluid", "checking coolant"]'::jsonb,0,'Dipstick check.','original'),
('127.877.d.7.C',4,'Most automatic transmission dipsticks should be read with the engine:','["off and in neutral only", "running and the transmission at operating temperature", "off and cold", "off and hot"]'::jsonb,1,'Check hot and running.','original'),
('127.877.d.7.D',3,'A technician removes a fill plug on the side of a transaxle with no dipstick to check the level. She is:','["checking oil", "checking coolant", "checking the fluid level in a transmission not equipped with a dipstick", "checking washer fluid"]'::jsonb,2,'Fill plug check.','original'),
('127.877.d.7.D',4,'On a transmission with a side fill plug, the level is correct when fluid:','["is 2 inches below", "pours out wildly", "fills past the top", "just reaches the bottom of the fill hole"]'::jsonb,3,'Level with the hole.','original'),
('127.877.d.7.E',3,'A technician sees fluid that is dark, smells burnt and drips from a seal. She is:','["checking the fluid condition and inspecting for leaks", "ignoring fluid", "guessing", "painting"]'::jsonb,0,'Condition and leaks.','original'),
('127.877.d.7.E',4,'Burnt-smelling transmission fluid usually indicates:','["a cold engine", "overheating and clutch wear", "a new fluid", "a clean unit"]'::jsonb,1,'Burnt means damage.','original'),
('127.877.d.7.F',3,'A technician drops the pan, replaces the filter and gasket and refills an automatic transmission to the specified amount. She is:','["changing oil", "changing coolant", "draining and replacing the fluid and filter in an automatic transmission", "changing tires"]'::jsonb,2,'ATF service.','original'),
('127.877.d.7.F',4,'The old fluid and filter from a transmission service should be:','["poured down a drain", "dumped", "burned", "disposed of according to environmental regulations"]'::jsonb,3,'Regulated waste.','original'),
('127.877.d.7.G',3,'A technician removes a gearbox''s drain plug, lets the oil drain and refills through the fill plug with the specified gear oil. She is:','["draining and replacing the fluid in a manual transmission or transaxle", "changing coolant", "changing tires", "changing wipers"]'::jsonb,0,'Manual service.','original'),
('127.877.d.7.G',4,'Metal particles found on the magnetic drain plug of a manual transmission may indicate:','["a new fluid", "internal gear or bearing wear", "a clean filter", "a perfect gearbox"]'::jsonb,1,'Wear debris.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_128'
from (values
('127.877.d.7.H',3,'A technician pries on the engine and transmission mounts with a bar and looks for cracked rubber or movement. She is:','["checking oil", "checking tires", "inspecting power train mounts", "checking wipers"]'::jsonb,2,'Mount check.','original'),
('127.877.d.7.H',4,'A worn engine mount can cause:','["better mileage", "a cooler engine", "quieter shifting", "vibration and clunking when accelerating"]'::jsonb,3,'Excess movement.','original'),
('127.877.d.8.A',3,'A technician locates the mass airflow sensor, the throttle position sensor and the oxygen sensor on an engine and explains what each does. She is:','["inspecting and explaining electrical and electronic components, sensors and actuators", "avoiding electronics", "painting", "guessing"]'::jsonb,0,'Sensors and actuators.','original'),
('127.877.d.8.A',4,'An oxygen sensor measures:','["oil level", "the oxygen content of the exhaust gases", "coolant temperature only", "tire pressure"]'::jsonb,1,'O2 sensor.','original'),
('127.877.d.8.B',3,'A technician connects a vacuum gauge to the intake manifold and reads the engine''s idle vacuum. She is performing:','["an oil test", "a tire test", "an engine absolute manifold pressure test", "a brake test"]'::jsonb,2,'Vacuum test.','original'),
('127.877.d.8.B',4,'A steady, low vacuum reading at idle can indicate:','["a new battery", "perfect health", "a full tank", "a vacuum leak or a mechanical problem"]'::jsonb,3,'Low vacuum is a clue.','original'),
('127.877.d.8.C',3,'A technician warms the engine and compares the scan tool''s coolant temperature with the thermostat''s rating. She is:','["verifying the engine operating temperature", "measuring oil", "measuring fuel", "measuring tires"]'::jsonb,0,'Check temperature.','original'),
('127.877.d.8.C',4,'An engine that never reaches normal operating temperature probably has:','["a dead radio", "a thermostat stuck open", "a bad tire", "a clogged filter"]'::jsonb,1,'Stuck-open thermostat.','original'),
('127.877.d.8.D',3,'A technician removes the spark plugs, checks the gap and inspects the wires and coils for cracks. She is:','["painting", "avoiding service", "removing and replacing spark plugs and inspecting secondary ignition components", "guessing"]'::jsonb,2,'Plug service.','original'),
('127.877.d.8.D',4,'Over-tightening a spark plug in an aluminum head can:','["reduce wear", "improve the seal", "cool the engine", "strip the threads"]'::jsonb,3,'Use proper torque.','original'),
('127.877.d.8.E',3,'A technician learns that a vehicle''s emissions monitors must run to completion before it can pass a readiness test. She is describing:','["the importance of operating all OBD II monitors for repair verification", "tire monitoring", "radio monitoring", "oil monitoring"]'::jsonb,0,'Complete monitors.','original'),
('127.877.d.8.E',4,'After clearing codes, the technician should drive the vehicle through a drive cycle so that:','["the tires wear", "the OBD II monitors can run and confirm the repair", "the battery drains", "the codes stay hidden"]'::jsonb,1,'Verify with monitors.','original'),
('127.877.d.8.F',3,'A technician connects a scan tool and records the diagnostic trouble codes, the monitor status and freeze-frame data. She is:','["guessing", "painting", "retrieving and recording diagnostic trouble codes and OBD II monitor status", "ignoring data"]'::jsonb,2,'Record data.','original'),
('127.877.d.8.F',4,'A code P0300 on a scan tool indicates:','["a weak tire", "a full tank", "low wiper fluid", "a random or multiple cylinder misfire"]'::jsonb,3,'P0300 = random misfire.','original'),
('127.877.d.8.G',3,'A technician tilts the airbox, examines the air filter for dirt, replaces it and checks the intake duct for cracks. She is:','["inspecting, servicing or replacing air filters, filter housings and intake ducts", "painting", "ignoring filters", "guessing"]'::jsonb,0,'Air filter service.','original'),
('127.877.d.8.G',4,'A restricted air filter can cause:','["better mileage", "reduced power and poor fuel economy", "a cooler engine", "more power"]'::jsonb,1,'Starved engine.','original'),
('127.877.d.8.H',3,'A technician relieves fuel pressure, disconnects the lines and installs a new in-line fuel filter in the right direction. She is:','["changing mirrors", "changing tires", "replacing fuel filters", "changing wipers"]'::jsonb,2,'Filter replacement.','original'),
('127.877.d.8.H',4,'Before disconnecting a fuel line, a technician should first:','["smoke nearby", "start the engine", "remove the battery cap", "relieve the fuel system pressure"]'::jsonb,3,'Safety first.','original'),
('127.877.d.8.I',3,'A technician inspects the exhaust manifold, pipes, muffler and catalytic converter for leaks and corrosion. She is:','["inspecting the integrity of the exhaust system", "guessing", "ignoring exhaust", "painting"]'::jsonb,0,'Exhaust check.','original'),
('127.877.d.8.I',4,'An exhaust leak ahead of the oxygen sensor can:','["help the engine", "cause false readings and poor fuel control", "clean the sensor", "cool the exhaust"]'::jsonb,1,'Leaks fool the sensor.','original'),
('127.877.d.8.J',3,'A technician checks the PCV valve and hoses for clogs and verifies the system draws crankcase vapors. She is:','["guessing", "painting", "inspecting, testing and servicing the positive crankcase ventilation system", "ignoring PCV"]'::jsonb,2,'PCV service.','original'),
('127.877.d.8.J',4,'A clogged PCV valve may cause:','["better efficiency", "cooler running", "less wear", "oil leaks and sludge from excessive crankcase pressure"]'::jsonb,3,'Pressure builds.','original'),
('127.877.d.9.A',3,'A technician reads a tire sidewall and finds the size, load rating, speed rating and the DOT manufacturing code. She is:','["identifying and interpreting tire sidewall data information", "guessing", "ignoring the tire", "painting"]'::jsonb,0,'Read the sidewall.','original'),
('127.877.d.9.A',4,'In a tire size of P215/60R16, the ''16'' refers to the:','["speed rating", "wheel diameter in inches", "aspect ratio", "tire width in millimeters"]'::jsonb,1,'Rim diameter.','original'),
('127.877.d.9.B',3,'A technician inserts a tread depth gauge in the groove and reads 3/32 inch. She is demonstrating:','["guessing", "painting", "tire tread depth measuring procedures using industry standards", "ignoring wear"]'::jsonb,2,'Measure tread.','original'),
('127.877.d.9.B',4,'A tire is generally considered worn out when the tread depth is:','["8/32 inch", "12/32 inch", "10/32 inch", "2/32 inch or less"]'::jsonb,3,'Wear bars at 2/32.','original'),
('127.877.d.9.C',3,'A technician spins a wheel on a balancer, adds weights to the rim and rechecks that it runs smooth. She is demonstrating:','["tire and wheel balance such as static and dynamic balance", "tire rotation", "tire inflation", "brake adjustment"]'::jsonb,0,'Balance.','original'),
('127.877.d.9.C',4,'An unbalanced front tire commonly causes:','["a dead battery", "a vibration in the steering wheel at highway speed", "a noisy radio", "lower tire pressure"]'::jsonb,1,'Vibration.','original'),
('127.877.d.9.D',3,'A technician uses a dial indicator to measure how much a wheel wobbles side to side and up and down. She is:','["measuring oil", "measuring coolant", "demonstrating tire and wheel measurements such as radial and lateral runout", "measuring fuel"]'::jsonb,2,'Runout.','original'),
('127.877.d.9.D',4,'Excessive wheel runout can cause:','["better handling", "longer tire life", "quieter ride", "vibration and uneven tire wear"]'::jsonb,3,'Wobble causes vibration.','original'),
('127.877.d.9.E',3,'A technician shakes the inner and outer tie rod ends and checks for play and torn boots. She is:','["inspecting steering linkage components and mounts", "painting", "guessing", "ignoring steering"]'::jsonb,0,'Steering check.','original'),
